/* Server-backed operations. No local mutation fallback. */
let server=null,operatorToken=sessionStorage.getItem('aquagrid_operator')||'';
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(operatorToken?{'Authorization':'Bearer '+operatorToken}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json();if(!r.ok){if(r.status===401){operatorToken='';sessionStorage.removeItem('aquagrid_operator')}throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail))}return data;}
async function refresh(){server=await api('telemetry');disrupted=server.disrupted;quarantined=server.quarantined;assets.splice(0,assets.length,...server.topology.assets);edges.splice(0,edges.length,...server.topology.edges);metrics();if(location.hash==='#control')setTab(tab);$('#backendStatus').textContent='PYTHON CONNECTED · '+(operatorToken?'OPERATOR':'READ ONLY');}
async function perform(fn){try{await fn();await refresh()}catch(e){toast(e.message);await refresh().catch(()=>{})}}
function factsList(rows){return rows.map(([k,v])=>`<div class="spec"><span>${escapeHTML(k)}</span><b>${escapeHTML(v)}</b></div>`).join('')}
function exportData(){let u=URL.createObjectURL(new Blob([JSON.stringify(server,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='aquagrid-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const oldMetrics=metrics;metrics=function(){if(!server)return;oldMetrics();$('#metrics').innerHTML=[['Production',server.production[0],'m³/h'],['Urban demand',server.demand,'m³/h'],['Stored reserve',server.storage_pct,'%'],['Modeled loss',server.loss,'m³/h'],['Active alerts',(server.leak.confirmed?1:0)+(server.quality_alert?1:0)+(server.quarantined?1:0),'']].map(([l,v,u])=>`<div class="metric"><span>${l}</span><strong>${v}</strong><small>${u}</small></div>`).join('')};
critical=a=>!!server&&server.leak.confirmed&&['SEC-04','V-04'].includes(a.id);
warn=a=>!!server&&server.quality_alert&&a.id==='INT-01';
const oldRenderNetwork=renderNetwork;renderNetwork=function(){if(!server)return;oldRenderNetwork();$$('#network .node').forEach(n=>{let a=asset(n.dataset.asset),sub=n.querySelector('.sub');if(!sub)return;if(a.type==='reservoir')sub.textContent=server.storage_pct+'% storage';if(a.type==='plant')sub.textContent=server.production[0]/2+' m³/h';if(a.type==='valve')sub.textContent=server.valve;if(a.type==='pump')sub.textContent=(server.demand+server.loss)+' m³/h';if(a.type==='intake')sub.textContent=(server.production[0]/.48).toFixed(0)+' m³/h'})};
inspect=function(id){if(!server)return;selected=id;renderNetwork();const a=asset(id);let rows=a.type==='reservoir'?[['Storage',server.storage_pct+'%'],['Combined capacity','10,000 m³'],['Safety floor','35%']]:a.type==='plant'?[['Production',server.production[0]/2+' m³/h'],['Scheduled total',server.production.join(', ')+' m³/h']]:a.type==='valve'?[['State',server.valve],['Leak loss',server.loss+' m³/h'],['Bypass capacity','150 m³/h']]:a.type==='sector'?[['Demand',(id==='SEC-04'?110:edges.find(e=>e[1]===id)[2])+' m³/h'],['Pressure',id==='SEC-04'?server.pressure_s4+' bar':'3.8 bar (illustrative)'],['Inflow',id==='SEC-04'?server.flow_s4+' m³/h':'Nominal demand']]:a.type==='intake'?[['Q-01',server.diagnostics.classification],['Quarantine',server.quarantined?'Yes':'No'],['Bloom warning',server.quality_alert?'Unresolved':'None']]:[['Delivery',server.demand+server.loss+' m³/h']];let links=edges.filter(e=>e[0]===id||e[1]===id).map(e=>e[0]===id?e[1]:e[0]);$('#assetInspector').innerHTML=`<span class="asset-type">${a.type.toUpperCase()} / ${a.id}</span><h3>${a.name}</h3><span class="asset-status ${critical(a)?'coral':warn(a)?'amber':''}">${critical(a)?'! LEAK EVIDENCE':warn(a)?'! QUALITY UNRESOLVED':'✓ MODELED STATE'}</span>${factsList(rows)}<h4>Connected assets</h4><p>${links.map(l=>`<button data-asset="${l}" style="color:var(--teal)">${l}</button>`).join(' · ')}</p><p>Server state v${server.version}. Telemetry sampled ${new Date(server.sampled_at*1000).toLocaleTimeString()}. All actions affect simulated assets only.</p><button class="outline" id="traceAsset">Trace upstream connections</button><button class="primary" data-tab="approvals">Review control proposals</button>`;$('#traceAsset').onclick=()=>{$('#traceToggle').checked=!$('#traceToggle').checked;inspect(id)}};
renderDetail=function(){if(!server){$('#detailPanel').innerHTML='<h2>Backend unavailable</h2><p>Start the Python service to access operations. No control changes can run offline.</p>';return}const el=$('#detailPanel');
if(tab==='energy'){let r=server.plans[plan],base=server.plans.baseline;el.innerHTML=`<p class="eyebrow">PYTHON PROJECTIONS</p><h2>Energy decisions are water decisions.</h2><p>Eight-hour Python mass-balance model. The optimizer minimizes energy cost over 100 m³/h steps, maintains the reserve floor and restores initial storage by 22:00. Quality gates still apply. All tariffs and thresholds are demo assumptions.</p><div class="segmented">${Object.entries({baseline:'Maintain production',shift:'Shift to off-peak',unsafe:'Aggressive throttle',optimized:'Optimize tariffs'}).map(([id,t])=>`<button data-plan="${id}" class="${id===plan?'active':''}">${t}</button>`).join('')}</div><div class="detail-grid"><div>${chart([{name:'Baseline',values:base.levels,color:'#506c70'},{name:'Selected',values:r.levels,color:'#c6ad80'}],35)}<p>Gold: selected · Grey: baseline · Coral: 35% floor</p>${chart([{name:'Hourly production',values:r.production,color:'#c6ad80'}],null,'m³/h')}</div><div class="detail-card"><span class="pill ${r.validation.passed?'':'coral'}">${r.validation.passed?'PASSES SAFETY CHECK':'BLOCKED BY SAFETY'}</span>${factsList([['Minimum reserve',r.min.toFixed(1)+'%'],['Modeled cost','$'+r.cost.toFixed(0)],['Savings vs baseline','$'+(base.cost-r.cost).toFixed(0)],['Violation hours',r.violations.join(', ')||'None']])}<p>${escapeHTML(r.validation.reasons.join(' ')||'Storage and water-quality checks pass. Human approval remains required.')}</p><button class="primary" id="stagePlan">Stage selected plan</button><p>Capacity 10,000 m³ · demand 550 m³/h · 3.5 kWh/m³ · $0.32/kWh peak, $0.12 off-peak. No hydraulic solver or pump-energy model.</p></div></div>`;$('#stagePlan').onclick=()=>perform(async()=>{await api('proposals',{kind:'schedule',production:r.production});tab='approvals'})}
if(tab==='diagnostics'){const d=server.diagnostics,l=server.leak;el.innerHTML=`<p class="eyebrow">PYTHON SENSOR DIAGNOSTICS</p><h2>Separate sensor failure from physical loss.</h2><div class="detail-grid"><div class="detail-card"><h3>Q-01 · Intake turbidity</h3><span class="pill ${server.quarantined?'amber':''}">${d.classification}${server.quarantined?' · QUARANTINED':''}</span>${chart([{name:'Q-01 raw samples',values:server.quality_samples,color:'#c6ad80'}],null,'NTU',['−7 min','−5 min','−3 min','Now'])}${factsList([['Rolling variance',d.variance?.toFixed(6)+' NTU²'],['Rate of change',d.rate_of_change?.toFixed(5)+' NTU/sample']])}<p>Eight-sample variance and range checks run in Python. Faulty Q-01 is automatically quarantined on disruption. Quarantine does not clear the independent bloom warning.</p></div><div class="detail-card"><h3>Sector 4 · Independent evidence</h3><span class="pill ${l.confirmed?'coral':''}">${l.classification}</span>${factsList([['Pressure',l.pressure_bar+' bar'],['Inflow',l.inflow_m3h+' m³/h'],['Expected demand','110 m³/h'],['Excess inflow',l.excess_m3h+' m³/h']])}<p>Demo leak rule: pressure below 2.5 bar and excess inflow above 30 m³/h. The pressure is an injected illustrative signature.</p><button class="outline" data-focus="SEC-04">Locate Sector 4</button></div></div>`}
if(tab==='incidents'){el.innerHTML=`<p class="eyebrow">INCIDENT CENTRE</p><h2>${server.disrupted?'Compound scenario active':'Baseline operations'}</h2><div class="detail-grid"><div class="detail-card"><h3>Independent network observations</h3>${factsList([['Sector 4 leak',server.leak.confirmed?'Confirmed in simulation':'No current evidence'],['Valve V-04',server.valve],['Intake Q-01',server.diagnostics.classification],['Bloom warning',server.quality_alert?'Unresolved':'None']])}<p>Protective leak isolation uses a modeled alternative 150 m³/h supply to Sector 4. This keeps its 110 m³/h demand served. Hydraulic transients are outside this MVP.</p><button class="primary" id="stageIsolation" ${server.leak.confirmed?'':'disabled'}>Stage safe isolation</button></div><div class="detail-card"><h3>Agent permission boundary</h3><p>The deterministic fallback can read telemetry and stage proposals. It cannot approve or invoke simulated actuators.</p><button class="outline" id="denyDirect">Test unauthorized valve command</button><pre id="denial" style="white-space:pre-wrap"></pre></div></div>`;$('#stageIsolation').onclick=()=>perform(async()=>{await api('proposals',{kind:'isolate'});tab='approvals'});$('#denyDirect').onclick=async()=>{try{await api('actuators/V-04',{})}catch(e){let message='403 BLOCKED: '+e.message;await refresh();$('#denial').textContent=message}}}
if(tab==='approvals'){el.innerHTML=`<p class="eyebrow">OPERATOR AUTHORIZATION</p><h2>Review. Validate. Authorize.</h2><p>Only an authenticated operator can authorize execution. Python revalidates telemetry freshness, proposal version, scenario version, reserves and applicable quality conditions inside one SQLite transaction.</p>${server.proposals.length?'':'<p>No proposals. Stage an isolation from Incident centre, or a schedule from Energy planning.</p>'}${server.proposals.map(p=>`<article class="detail-card" style="margin-top:20px"><span class="pill ${p.status.includes('BLOCKED')?'coral':''}">${p.status}</span><h3 style="margin-top:20px">${p.action.kind==='isolate'?'Close V-04 and feed Sector 4 through bypass':'Apply production schedule'}</h3><p>${escapeHTML(p.safety.reasons.join(' ')||'Server safety checks passed at staging. Execution requires fresh checks.')}</p>${factsList([['Proposal',p.id],['Version',p.version],['State version',p.state_version],['Created',new Date(p.created_at*1000).toLocaleTimeString()],['Expires',new Date(p.expires_at*1000).toLocaleTimeString()],['Minimum projected reserve',p.safety.projection.min.toFixed(1)+'%']])}<p>${p.action.kind==='isolate'?'Impact: eliminate 65 m³/h modeled leak; 110 m³/h delivered through the separate bypass.':'Proposed hourly setpoints: '+p.action.production.join(', ')+' m³/h'}</p>${p.status==='PENDING_APPROVAL'?`<button class="primary" data-decision="${p.id}" data-version="${p.version}">Review approval</button> <button class="outline" data-reject="${p.id}" data-version="${p.version}">Reject proposal</button>`:''}</article>`).join('')}`}
if(tab==='audit'){el.innerHTML=`<p class="eyebrow">PERSISTENT AUDIT HISTORY</p><h2>Every decision, recorded.</h2><p>SQLite append-only audit table. Reset creates a new scenario epoch and preserves history. This local database is not a tamper-proof external ledger.</p><button class="outline" id="export">Export executive report</button>${server.audit.map(a=>`<article class="event"><time>#${a.seq}<br>${new Date(a.at*1000).toLocaleTimeString()}</time><div><h3>${escapeHTML(a.event)}</h3><p>${escapeHTML(a.actor)}</p><pre style="white-space:pre-wrap;word-break:break-word;font-size:12px;color:var(--muted)">${escapeHTML(JSON.stringify(a.body,null,2))}</pre></div></article>`).join('')}`;$('#export').onclick=exportData}
};
async function approveProposal(id,version,approve){await perform(async()=>{if(approve){const dialog=$('#approveDialog');dialog.querySelector('p').textContent='Authorize proposal '+id+'? Python will revalidate and execute it once in the simulated network.';dialog.showModal();const yes=await new Promise(resolve=>{dialog.onclose=()=>resolve(dialog.returnValue==='approve')});if(!yes)return}await api('proposals/'+id+'/decision',{version,approve})})}
document.addEventListener('click',e=>{let a=e.target.closest('[data-decision],[data-reject]');if(a)approveProposal(a.dataset.decision||a.dataset.reject,+a.dataset.version,!!a.dataset.decision)});
$('#disrupt').onclick=()=>perform(()=>api('scenario/disrupt',{}));$('#reset').onclick=()=>perform(async()=>{await api('scenario/reset',{});plan='baseline';tab='twin';selected='RES-02'});
$('#loginForm').onsubmit=async e=>{e.preventDefault();await perform(async()=>{let result=await api('auth/login',{password:$('#operatorPassword').value});operatorToken=result.token;sessionStorage.setItem('aquagrid_operator',operatorToken);$('#operatorPassword').value='';$('#loginDialog').close();toast('Signed in as demo operator')})};
$('#operatorLogin').onclick=()=>{if(operatorToken){operatorToken='';sessionStorage.removeItem('aquagrid_operator');refresh()}else $('#loginDialog').showModal()};$('#sampleTelemetry').onclick=()=>perform(()=>api('scenario/sample',{}));
$('#exportReport').onclick=exportData;
refresh().catch(()=>{$('#backendStatus').textContent='BACKEND OFFLINE';$('#disrupt').disabled=true;$('#reset').disabled=true;$('#metrics').innerHTML='<p style="padding:15px">Python service unavailable. Start scripts/run.sh and open http://127.0.0.1:8000.</p>';$('#network').innerHTML='';$('#assetInspector').innerHTML='<p>Connect to the Python backend to view authoritative simulation data.</p>';if(tab!=='twin')renderDetail()});

showRoute();
